fn format_duration_minutes(mins: i64) -> String {
    if mins <= 0 {
        return "<1m".to_string();
    }
    if mins < 10 {
        return format!("0{}m", mins);
    }
    if mins < 60 {
        return format!("{}m", mins);
    }
    let h = mins / 60;
    let m = mins % 60;
    return format!("{}h {:02}m", h, m);
}

