// ---------- table helpers ----------
fn char_width(s: &str) -> usize {
    s.chars().count()
}

fn pad_nbsp(s: &str, width: usize) -> String {
    let len = char_width(s);
    if len >= width {
        s.to_string()
    } else {
        let mut out = s.to_string();
        for _ in 0..(width - len) {
            out.push('\u{a0}');
        }
        out
    }
}

fn format_list_table(bin: &str, activities: &[(NaiveDateTime, Option<NaiveDateTime>, String, String, i64)], grouped: bool, single_day: bool, no_grouping_single_day: bool) -> String {
