        ("global", 'f') => "-f <FILE>".to_string(),
        (_, 'd') => "--description <DESCRIPTION>".to_string(),
        (_, 'p') => {
            // for status/list/report/start/change/continue, -p is --project
            "--project <PROJECT>".to_string()
        },
        (_, 't') => "--time <TIME>".to_string(),
