// ---------- generic parser for remaining commands ----------
// Spec for an option
#[derive(Clone)]
struct OptDef {
    long: String, // e.g., "description", "project", "time", "help", "current_week", etc. For edit -e (no long), long is "e" with is_short_only=true?
    short: Option<char>, // e.g., Some('d')
    takes_value: bool, // true for options with value, false for flags
    value_name: String, // e.g., "DESCRIPTION", "PROJECT", "TIME", etc. For flags, empty.
    required: bool, // only for start's description/project (but start already handled separately, so not needed here)
    optional_value: bool, // true for last's -n/--number (optional value, default 10)
    short_only: bool, // true for edit -e and global -f (no long)? For edit, display is "-e <editor>", not "--e". For others, display is long form.
}

fn opt_display_for_def(def: &OptDef) -> String {
    if def.short_only {
        if def.takes_value {
            format!("-{} <{}>", def.short.unwrap(), def.value_name)
        } else {
            format!("-{}", def.short.unwrap())
        }
    } else {
        if def.takes_value {
            format!("--{} <{}>", def.long, def.value_name)
        } else {
            format!("--{}", def.long)
        }
    }
}

// Generic parse result
