    values: BTreeMap<String, String>, // long -> value (for flags, value is "true" if present? Actually for flags, presence indicates set, value not needed. We'll store "true" for flags.)
    positionals: Vec<String>,
    provided_longs: BTreeSet<String>, // set of longs provided (for usage)
}

