    let parsed = generic_parse(bin, "report", args, &defs, None, None);
    let mut date_present: BTreeSet<String> = BTreeSet::new();
    for k in ["current_week","last_week","today","yesterday","date","from","to"] {
        if parsed.values.contains_key(k) {
            date_present.insert(k.to_string());
        }
    }
    check_date_conflicts(bin, "report", &date_present);
    let mut arg_errors: Vec<String> = Vec::new();
    let mut date_opt: Option<NaiveDate> = None;
    let mut from_opt: Option<NaiveDate> = None;
    let mut to_opt: Option<NaiveDate> = None;
    if let Some(v) = parsed.values.get("date") {
        match parse_date_arg(v, "-d/--date") {
            Ok(d) => date_opt = Some(d),
            Err(e) => arg_errors.push(e),
        }
    }
    if let Some(v) = parsed.values.get("from") {
        match parse_date_arg(v, "--from") {
            Ok(d) => from_opt = Some(d),
            Err(e) => arg_errors.push(e),
        }
    }
    if let Some(v) = parsed.values.get("to") {
        match parse_date_arg(v, "--to") {
            Ok(d) => to_opt = Some(d),
            Err(e) => arg_errors.push(e),
        }
    }
    let mut round_minutes: Option<i64> = None;
    if let Some(v) = parsed.values.get("round") {
        match parse_round_arg(v) {
            RoundResult::Valid(m) => round_minutes = Some(m),
            RoundResult::InvalidWithError(e) => arg_errors.push(e),
            RoundResult::Ignored => {},
        }
    }
    let project_filter = parsed.values.get("project").cloned();
    let today_flag = parsed.values.contains_key("today");
    let yesterday_flag = parsed.values.contains_key("yesterday");
    let current_week_flag = parsed.values.contains_key("current_week");
    let last_week_flag = parsed.values.contains_key("last_week");

    let lines = match read_bartib_file(file) {
        Ok(l) => l,
        Err(e) => { eprint!("Error: Could not read from file: {}\n\nCaused by:\n    {}\n", file, e); process::exit(1); }
    };
    let warnings = warnings_for_lines(&lines);
    let mut out_prefix = String::new();
    for e in &arg_errors { out_prefix.push_str(e); }
    out_prefix.push_str(&warnings);

    let acts = activities_from_lines(&lines);
    let now = now_naive();
    struct ProcAct { rounded_start: NaiveDateTime, project: String, description: String, dur_mins: i64 }
    let mut proc: Vec<ProcAct> = Vec::new();
    for a in acts {
        let (rs, dur) = if let Some(rm) = round_minutes {
            let rs = round_datetime(&a.start, rm);
            if let Some(e) = a.end {
                let re = round_datetime(&e, rm);
                (rs, duration_between(&rs, &re))
            } else {
                (rs, duration_running(&rs, &now))
            }
        } else {
            if let Some(e) = a.end {
                (a.start, duration_between(&a.start, &e))
            } else {
                (a.start, duration_running(&a.start, &now))
            }
        };
        proc.push(ProcAct { rounded_start: rs, project: a.project, description: a.description, dur_mins: dur });
    }
    if let Some(pf) = &project_filter {
        proc.retain(|p| &p.project == pf);
    }
    let today = today_date();
    let yesterday = today - Duration::days(1);
    let monday = monday_of_week(today);
    let last_monday = monday - Duration::days(7);
    let last_sunday = monday - Duration::days(1);
    if today_flag {
        proc.retain(|p| p.rounded_start.date() == today);
    } else if yesterday_flag {
        proc.retain(|p| p.rounded_start.date() == yesterday);
    } else if current_week_flag {
        let sunday = monday + Duration::days(6);
        proc.retain(|p| p.rounded_start.date() >= monday && p.rounded_start.date() <= sunday);
    } else if last_week_flag {
        proc.retain(|p| p.rounded_start.date() >= last_monday && p.rounded_start.date() <= last_sunday);
    } else if let Some(d) = date_opt {
        proc.retain(|p| p.rounded_start.date() == d);
    } else {
        if let Some(f) = from_opt { proc.retain(|p| p.rounded_start.date() >= f); }
        if let Some(t) = to_opt { proc.retain(|p| p.rounded_start.date() <= t); }
    }
    // Aggregate by project -> description
    let mut projects: BTreeMap<String, BTreeMap<String, i64>> = BTreeMap::new();
    let mut total: i64 = 0;
    for p in proc {
        total += p.dur_mins;
        let entry = projects.entry(p.project.clone()).or_insert(BTreeMap::new());
        *entry.entry(p.description.clone()).or_insert(0) += p.dur_mins;
    }
    print!("{}{}", out_prefix, format_report(&projects, total));
}

fn cmd_status(bin: &str, args: &[String], file: &str) {
    let defs = vec![
        OptDef { long: "help".to_string(), short: Some('h'), takes_value: false, value_name: "".to_string(), required: false, optional_value: false, short_only: false },
        OptDef { long: "project".to_string(), short: Some('p'), takes_value: true, value_name: "PROJECT".to_string(), required: false, optional_value: false, short_only: false },
    ];
    let parsed = generic_parse(bin, "status", args, &defs, None, None);
    let project_filter = parsed.values.get("project").cloned();
    let lines = match read_bartib_file(file) {
        Ok(l) => l,
        Err(e) => { eprint!("Error: Could not read from file: {}\n\nCaused by:\n    {}\n", file, e); process::exit(1); }
    };
    let warnings = warnings_for_lines(&lines);
    if !warnings.is_empty() { print!("{}", warnings); }
    let acts = activities_from_lines(&lines);
    let now = now_naive();
    let today = today_date();
    let monday = monday_of_week(today);
    let sunday = monday + Duration::days(6);
    let month_start = NaiveDate::from_ymd_opt(today.year(), today.month(), 1).unwrap();
    // month end: first day of next month -1 day
    let (next_year, next_month) = if today.month() == 12 { (today.year()+1, 1) } else { (today.year(), today.month()+1) };
    let next_month_start = NaiveDate::from_ymd_opt(next_year, next_month, 1).unwrap();
    let month_end = next_month_start - Duration::days(1);

    // Filter by project if present (for totals and NOW)
    let mut filtered = acts.clone();
    if let Some(pf) = &project_filter {
        filtered.retain(|a| &a.project == pf);
    }
    // Find running (first running sorted by start? As observed for multiple running, status NOW shows first (earliest)? For two running 08:00 and 09:00, status showed 08:00 (earliest). Good. So sorted by start, first.
    let mut running: Vec<&Activity> = filtered.iter().filter(|a| a.end.is_none()).collect();
    running.sort_by(|a,b| a.start.cmp(&b.start));
    let now_desc = if let Some(r) = running.first() {
        let mins = duration_running(&r.start, &now);
        Some((r.description.clone(), r.project.clone(), mins))
    } else { None };

    // Totals: today, week, month (using start date, including running durations with now)
    let mut today_sum: i64 = 0;
    let mut week_sum: i64 = 0;
    let mut month_sum: i64 = 0;
    for a in &filtered {
        let dur = if let Some(e) = &a.end {
            duration_between(&a.start, e)
        } else {
            duration_running(&a.start, &now)
        };
        let d = a.start.date();
        if d == today { today_sum += dur; }
        if d >= monday && d <= sunday { week_sum += dur; }
        if d >= month_start && d <= month_end { month_sum += dur; }
    }
    print!("{}", format_status(now_desc, today_sum, week_sum, month_sum, project_filter.as_deref()));
}

