    match=(o1_out==o2_out and o1_err==o2_err and r1.returncode==r2.returncode)
    if file_content is not None:
        c1=open(tf1).read() if os.path.exists(tf1) else "NOFILE"
        c2=open(tf2).read() if os.path.exists(tf2) else "NOFILE"
        file_match=(c1==c2)
    else:
        file_match=True; c1=c2=""
    if not (match and file_match):
        print(f"FAIL {args}")
        print(f"  rc1={r1.returncode} rc2={r2.returncode}")
        if o1_out!=o2_out: print(f"  orig out={repr(r1.stdout[:1200])}\n  new  out={repr(r2.stdout[:1200])}")
        if o1_err!=o2_err: print(f"  orig err={repr(r1.stderr[:800])}\n  new  err={repr(r2.stderr[:800])}")
        if not file_match: print(f"  orig file={repr(c1[:800])}\n  new  file={repr(c2[:800])}")
        return False
    else:
        print(f"PASS {args}")
        return True

